    with a 5-second timeout and a User-Agent header 'inventory-sync/1.0' on every request.
    """
    proxies = {
        "http://": proxy_url,
        "https://": proxy_url,
    }
    headers = {
        "User-Agent": "inventory-sync/1.0",
    }
    timeout = 5.0
    return httpx.Client(base_url=base_url, proxies=proxies, timeout=timeout, headers=headers)

