from marshmallow import Schema, fields, validate, ValidationError, EXCLUDE


class SignupSchema(Schema):
    username = fields.String(
        required=True,
        validate=validate.Regexp(
            r"^[a-zA-Z0-9]+$", error="Must be an alphanumeric string"
        ),
    )
    email = fields.Email(required=True)
    plan = fields.String(
        load_default="free",
        validate=validate.OneOf(["free", "pro", "team"]),
    )
    age = fields.Integer(
        validate=validate.Range(min=16, max=120),
        load_default=None,
    )

    class Meta:
        unknown = EXCLUDE


def validate_signup(data: dict) -> dict:
    schema = SignupSchema()
    try:
        result = schema.load(data)
    except ValidationError as err:
        exc = ValueError("Invalid input")
        exc.messages = err.messages
        raise exc
    # Remove age if None (not provided)
    if result.get("age") is None:
        result.pop("age")
    return result

from importlib.metadata import distributions, PackageNotFoundError, version

def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each given distribution name (case-insensitive) to its installed version string,
    or None if not installed.
    """
    # Build a mapping of lowercased distribution names to their canonical names
    installed = {dist.metadata["Name"].lower(): dist.metadata["Name"] for dist in distributions() if dist.metadata["Name"]}
    result: dict[str, str | None] = {}
    for name in names:
        lower_name = name.lower()
        if lower_name in installed:
            try:
                ver = version(installed[lower_name])
            except PackageNotFoundError:
                ver = None
            result[name] = ver
        else:
            result[name] = None
    return result

